harness.live_gates.mjs:
// Before/after harness for syzygy-bpyt.6.2: evaluates both owner-act gates
// through their production loaders over one governance revision, and runs
// the owner-act parser over every tracked Markdown file at that revision,
// testing each parsed Owner value against both former rules and the
// current shared rule. Usage: node live_gates.mjs <worktree> <revision> <out.json>
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';

const [root, revision, out] = process.argv.slice(2);
const core = await import(pathToFileURL(join(root, 'packages/three-surface-poc-core/dist/index.js')).href);
const gov = await import(pathToFileURL(join(root, 'apps/three-surface-poc/dist/governance-inputs.js')).href);
const walk = await import(pathToFileURL(join(root, 'apps/three-surface-poc/dist/walkthrough-inputs.js')).href);
let shared;
try {
  shared = await import(pathToFileURL(join(root, 'packages/three-surface-poc-core/dist/act-fields.js')).href);
} catch {
  shared = undefined;
}

const OLD_BODY = /^(agent|bot|machine|service|system|ci|pipeline|model)([:\s-]|$)|\b(claude|codex|gpt|copilot|llm)\b/i;
const OLD_JUDGMENT = /^(?:agent|bot|ci|system|daemon|service|pipeline|automation|model|claude|syzygy)(?:[\s:/-]|$)|(?:\[bot\]|-bot|-agent)$/i;
const INSTANT = '2026-10-21T12:00:00Z';
const options = { repoRoot: root, governanceRevision: revision, evaluationInstant: INSTANT };

const body = core.evaluateBodyReadAuthority(
  gov.loadBodyReadAuthorityInputs({ ...options, evaluationId: 'evaluation:pwb-body-read:bpyt-6-2' }),
);
const judgmentInputs = walk.walkthroughJudgmentInputsFor({
  ...options,
  evaluationId: 'evaluation:pwb-walkthrough-judgment:bpyt-6-2',
})({ evaluationIdentity: 'bpyt-6-2' });
const judgment = core.evaluateWalkthroughJudgment(judgmentInputs);

const files = execFileSync('git', ['-C', root, 'ls-tree', '-r', '-z', '--name-only', revision], { maxBuffer: 1 << 28 })
  .toString('utf8')
  .split('\0')
  .filter((path) => path.endsWith('.md'));
const owners = [];
for (const path of files) {
  const text = execFileSync('git', ['-C', root, 'show', `${revision}:${path}`], { maxBuffer: 1 << 28 }).toString('utf8');
  const parsed = core.parseOwnerActRecord(text);
  if (parsed.owner.kind === 'missing') continue;
  const value = parsed.owner.kind === 'present' ? parsed.owner.value : parsed.owner.raw;
  owners.push({
    path,
    kind: parsed.owner.kind,
    value,
    oldBody: OLD_BODY.test(value),
    oldJudgment: OLD_JUDGMENT.test(value),
    shared: shared === undefined ? null : shared.NON_HUMAN_PRINCIPAL.test(value),
  });
}

writeFileSync(
  out,
  JSON.stringify(
    {
      revision,
      markdownFiles: files.length,
      ownerFields: owners.length,
      distinctOwnerValues: [...new Set(owners.map((row) => row.value))],
      owners,
      bodyRead: body,
      walkthroughJudgment: judgment,
    },
    null,
    2,
  ) + '\n',
);
console.log(`md ${files.length} owners ${owners.length} body.admits ${body.admits} judgment ${judgment.outcome.kind}`);

harness.owner_sweep.py:
import re, subprocess, sys, json
OLD_BODY = re.compile(r'^(agent|bot|machine|service|system|ci|pipeline|model)([:\s-]|$)|\b(claude|codex|gpt|copilot|llm)\b', re.I)
OLD_JUDG = re.compile(r'^(?:agent|bot|ci|system|daemon|service|pipeline|automation|model|claude|syzygy)(?:[\s:/-]|$)|(?:\[bot\]|-bot|-agent)$', re.I)
files = subprocess.run(['git','ls-files','-z'], capture_output=True, check=True).stdout.decode().split('\0')
rows = []
for f in files:
    if not f.endswith('.md'): continue
    try: text = open(f, encoding='utf-8').read()
    except Exception: continue
    for i, line in enumerate(text.split('\n'), 1):
        m = re.match(r'^\s*(?:[-*]\s+)?(?:\*\*)?Owner:(?:\*\*)?\s*(.*)$', line)
        if m: rows.append((f, i, m.group(1).strip()))
vals = {}
for f, i, v in rows:
    vals.setdefault(v, []).append(f'{f}:{i}')
print('owner lines', len(rows), 'files', len({r[0] for r in rows}), 'distinct values', len(vals))
flips = []
for v, locs in sorted(vals.items()):
    b, j = bool(OLD_BODY.search(v)), bool(OLD_JUDG.search(v))
    if b != j: flips.append((v, b, j, locs))
    print(json.dumps(v), 'body', b, 'judg', j, len(locs))
print('DIVERGENT', len(flips))
for x in flips: print(x)
